CREATE OR REPLACE FUNCTION app_security.consume_reset(hash_value text, password_value text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE account_id bigint; token_id bigint; account_email text;
BEGIN
    SELECT customer_id INTO account_id FROM public.password_reset_tokens WHERE token_hash = hash_value;
    IF account_id IS NULL THEN RETURN NULL; END IF;
    PERFORM id FROM public.customers WHERE id = account_id FOR UPDATE;
    SELECT id INTO token_id FROM public.password_reset_tokens
        WHERE token_hash = hash_value AND NOT used AND expires_at > LOCALTIMESTAMP FOR UPDATE;
    IF token_id IS NULL THEN RETURN NULL; END IF;
    UPDATE public.customers SET password = password_value WHERE id = account_id RETURNING email INTO account_email;
    UPDATE public.password_reset_tokens SET used = true WHERE id = token_id;
    DELETE FROM public.password_reset_tokens WHERE customer_id = account_id AND NOT used;
    RETURN account_email;
END $function$

functions.create_reset(email_value text, hash_valu:
CREATE OR REPLACE FUNCTION app_security.create_reset(email_value text, hash_value text, expiry timestamp without time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE account_id bigint; recipient text;
BEGIN
    SELECT id, email INTO account_id, recipient FROM public.customers WHERE email = email_value FOR UPDATE;
    IF account_id IS NULL THEN RETURN NULL; END IF;
    IF hash_value !~ '^[0-9a-f]{64}$' OR expiry <= LOCALTIMESTAMP OR expiry > LOCALTIMESTAMP + interval '31 minutes' THEN
        RAISE EXCEPTION 'Invalid recovery request' USING ERRCODE = '22023';
    END IF;
    DELETE FROM public.password_reset_tokens WHERE customer_id = account_id AND NOT used;
    INSERT INTO public.password_reset_tokens (customer_id, token_hash, expires_at, created_at, used)
    VALUES (account_id, hash_value, expiry, LOCALTIMESTAMP, false);
    RETURN recipient;
END $function$

functions.guard_account_update():
CREATE OR REPLACE FUNCTION app_security.guard_account_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE expected_role text;
BEGIN
    IF current_user = pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid = TG_RELID)) THEN RETURN NEW; END IF;
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.environment_admin IS DISTINCT FROM OLD.environment_admin THEN
        RAISE EXCEPTION 'Operation is not permitted' USING ERRCODE = '42501';
    END IF;
    IF (NEW.access_level IS DISTINCT FROM OLD.access_level OR NEW.role IS DISTINCT FROM OLD.role)
       AND app_security.actor_role() <> 'SUPER_ADMIN' THEN
        RAISE EXCEPTION 'Operation is not permitted' USING ERRCODE = '42501';
    END IF;
    expected_role := CASE NEW.access_level
        WHEN 1 THEN 'ADMIN' WHEN 2 THEN 'ADMIN' WHEN 3 THEN 'SUPER_ADMIN'
        WHEN 4 THEN 'DRIVER' ELSE 'USER' END;
    IF NEW.role IS DISTINCT FROM expected_role THEN
        RAISE EXCEPTION 'Role and access level are inconsistent' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $function$

functions.guard_order_relationship():
CREATE OR REPLACE FUNCTION app_security.guard_order_relationship()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE column_name text;
BEGIN
    IF current_user = pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid = TG_RELID)) THEN RETURN NEW; END IF;
    FOREACH column_name IN ARRAY TG_ARGV LOOP
        IF (to_jsonb(NEW) -> column_name) IS DISTINCT FROM (to_jsonb(OLD) -> column_name) THEN
            RAISE EXCEPTION 'Operation is not permitted' USING ERRCODE = '42501';
        END IF;
    END LOOP;
    RETURN NEW;
END $function$

functions.validate_special_selection_relationship(:
CREATE OR REPLACE FUNCTION app_security.validate_special_selection_relationship()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE special_order_id bigint; selected_order_id bigint;
BEGIN
    SELECT s.order_id INTO special_order_id
    FROM public.order_special_item s
    WHERE s.order_special_item_id = NEW.order_special_item_id;
    IF NEW.order_menu_item_id IS NOT NULL THEN
        SELECT m.order_id INTO selected_order_id FROM public.order_menu_item m
        WHERE m.order_menu_item_id = NEW.order_menu_item_id;
    ELSE
        SELECT p.order_id INTO selected_order_id FROM public.order_pizza_item p
        WHERE p.order_pizza_item_id = NEW.order_pizza_item_id;
    END IF;
    IF special_order_id IS NULL OR selected_order_id IS NULL OR special_order_id <> selected_order_id THEN
        RAISE EXCEPTION 'Special selection must reference an item from the same order' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $function$

functions.verified_customer_id():
CREATE OR REPLACE FUNCTION app_security.verified_customer_id()
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    candidate bigint;
    signing_key text;
    supplied_signature text;
    expected_signature text;
    payload text;
BEGIN
    BEGIN
        candidate := nullif(current_setting('app.customer_id', true), '')::bigint;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN NULL;
    END;
    supplied_signature := nullif(current_setting('app.context_signature', true), '');
    IF candidate IS NULL OR candidate <= 0 OR supplied_signature IS NULL THEN
        RETURN NULL;
    END IF;
    SELECT s.secret INTO signing_key
    FROM app_security.rls_context_secret s
    WHERE s.singleton;
    IF signing_key IS NULL THEN RETURN NULL; END IF;
    payload := 'rls-context-v1|' || candidate::text || '|' || pg_backend_pid()::text
        || '|' || pg_current_xact_id()::text;
    expected_signature := encode(public.hmac(payload, signing_key, 'sha256'), 'hex');
    IF supplied_signature <> expected_signature THEN RETURN NULL; END IF;
    RETURN candidate;
END $function$

functions.verified_environment_admin():
CREATE OR REPLACE FUNCTION app_security.verified_environment_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    signing_key text;
    supplied_signature text;
    expected_signature text;
    payload text;
BEGIN
    IF current_setting('app.environment_admin', true) IS DISTINCT FROM 'true' THEN
        RETURN false;
    END IF;
    supplied_signature := nullif(current_setting('app.context_signature', true), '');
    IF supplied_signature IS NULL THEN RETURN false; END IF;
    SELECT s.secret INTO signing_key FROM app_security.rls_context_secret s WHERE s.singleton;
    IF signing_key IS NULL THEN RETURN false; END IF;
    payload := 'rls-context-v1|environment-admin|' || pg_backend_pid()::text
        || '|' || pg_current_xact_id()::text;
    expected_signature := encode(public.hmac(payload, signing_key, 'sha256'), 'hex');
    RETURN supplied_signature = expected_signature;
END $function$
